UPDATE expert_service_offerings SET name = $new$Local Picks Session$new$ WHERE NOT EXISTS (SELECT 1 FROM expert_service_offerings e2 WHERE e2.name = $k$Local Picks Session$k$) AND name = $old$Hidden Gems Insider Session$old$;
